[grammar(u,'三81','X 什么啊！','Recognize an emotional rhetorical challenge','怕什么啊 may challenge or reassure someone’s fear, rather than ask the name of a feared object. In a friendly conversation it can still sound dismissive; 我陪你 is often kinder. Read context and intonation, and do not infer permission.',[('怕什么啊，我陪你。','What is there to fear? I will accompany you.'),('急什么啊，还没到时间。','Why rush? The time has not come yet.'),('笑什么啊，先听我说完。','What are you laughing at? Hear me out first.')],('怕什么啊一定是温柔安慰。','要看语气，也可能显得不耐烦。','The pattern can be dismissive depending on delivery.')),
grammar(u,'三19','并 + 没有 / 不：再辨范围','Retrieve emphatic denial','我并没有取消 denies cancelling; it does not deny changing the room. Retrieve the earlier emphatic negation by specifying exactly what is denied. A strong denial remains an assertion, not external proof.',[('我并没有取消，只换了房间。','I did not cancel; I only changed the room.'),('她并不讨厌这部剧。','She does not dislike this series.'),('我并没有替你报名。','I did not register for you.')],('并没有取消说明地点也没有变。','没有取消，地点仍可能变了。','The denial has a specified scope.'))],
('A joke at the theatre','Find what was denied and why a joke needs care.',[('连续剧明天播出，今天剧场里演话剧。','The series broadcasts tomorrow; today a play is performed in the theatre.'),('导演喊怕什么啊，是在安慰吗？','The director shouts 怕什么啊. Is it reassurance?'),('要看语气。我陪你可能更清楚，不替对方决定害不害怕。','It depends on delivery. I will accompany you may be clearer; do not decide the other person’s fear.'),('你并没有取消活动，地点也没变吗？','You did not cancel. Did the place also stay the same?'),('我只否认取消，房间换了。记者也要问具体范围。','I only deny cancellation; the room changed. The reporter should ask the exact scope too.'),('眼前的旧直播录像不是今天现场。收音机有海浪声，不代表这里是海边。','The old broadcast recording is not today’s site. Radio sea sounds do not mean this is the seaside.')],[('detail','What was changed?',['The room','The cancellation decision','Nothing'],0),('inference','Does 怕什么啊 always sound kind?',['No','Yes','Only in a theatre'],0)],[],True),
('Warm teasing needs an answer','Read the media note.',[('她热爱影视，迎接朋友时先问到达时间；性别不决定节目喜好。','She loves film and TV and checks arrival time when welcoming friends; gender does not determine preferences.'),('古城故事为人所知，伟大是评价，重大要说明影响，不能把评价当证据。','The ancient-city story is known; great is an evaluation and significant needs scope; evaluations are not evidence.'),('直线和准确时间要核对，眼前看见的不是全部背景。','Check straight lines and accurate times; what is before us is not all background.'),('咖啡放在一边，她好奇地听，播放以后仍可以说没听懂。','She sets coffee aside and listens curiously; after playback she may still say she did not understand.'),('话剧里的笑和咆哮属于演戏，连续剧里的情绪不替演员说明私人经历。','Laughter and roaring in a play are acting; series emotions do not describe actors’ private lives.')],[('mainidea','What is the key distinction?',['Performance, interpretation and actual facts','A recording and the present treated as one','Popularity as universal approval'],0)],[(3,'播放')],False),
('What are you laughing at?','Read an original comic scene.',[('笑什么啊，我还没讲到好笑的地方。','What are you laughing at? I have not reached the funny part.'),('我笑自己的咖啡放错杯子了，不是笑你。','I laugh at having put my coffee in the wrong cup, not at you.'),('好，那先把杯子放对，我再讲。','Good; fix the cup first, then I will continue.')],[('inference','What clears up the misunderstanding?',['Naming the actual target of laughter','Assuming the listener consented','Making the actor’s feelings factual'],0)],[],True),
dict(tf=[('直播','这是旧直播的录像。','This is a recording of an old broadcast.','It is necessarily live now.',False,'Old recorded material is not current live transmission.'),('为','话剧为人所知，不一定人人喜欢。','The play is known, not necessarily universally liked.','Universal liking is unproven.',True,'Knowledge differs from liking.')],reply=[('准','这个时间准吗？','Is this time accurate?',['还没核对，先看记录。','标题大就准确。','笑了就是确认。'],0,'Check the time.'),('迎接','她什么时候到？','When will she arrive?',['先问她本人，再去迎接。','性别决定时间。','节目播出就说明到了。'],0,'Ask the actual person.')],fill=[('导演','导演介绍这段场景。','The director introduces this scene.'),('剧场','剧场门口有通知。','The theatre entrance has a notice.')],match=[('演',[('怕什么啊，我陪你。','What is there to fear? I will accompany you.'),('我并没有取消，只换了房间。','I did not cancel; only the room changed.'),('先播放这一小段。','Play this short passage first.')]),('记者',[('记者问了来源。','The reporter asked the source.'),('性别不决定喜好。','Gender does not determine preferences.'),('演得认真不是事实证明。','Serious acting is not proof of fact.')])]),
