[grammar(u,'三54','把 + 对象 + 动作结果：再应用','Retrieve object handling in the chat','把旧牌子换成新牌子 states an object and intended or actual result depending on context. 已经把…换了 reports completion; 要把…换 states a requirement. A plan is not a finished action.',[('要把旧牌子换成新牌子。','Replace the old sign with the new one.'),('已经把时间改了。','The time has already been changed.'),('把两条信息组合起来看。','Consider the two messages together.')],('要把牌子换了，表示已经完成。','要换是要求，不是已经完成。','Requirement and completion differ.')),
grammar(u,'三55','被 + 动作：同一事件换视角','Retrieve the affected item in a passive','她把时间改了 / 时间被她改了 describe the same event with different focus. 时间被改了 leaves the agent unnamed. No added blame follows merely from using the passive.',[('她把时间改了。','She changed the time.'),('时间被她改了。','The time was changed by her.'),('牌子被换成新的了。','The sign was replaced by a new one.')],('时间被改了，一定是我改的。','时间被改了，还没说是谁改的。','An unnamed agent remains unknown.'))],
('One last group-chat check','Find the final agreement and remaining uncertainty.',[('游戏结束了，这个单元也完成了，算等级认证吗？','The game ended and the unit finished; does that certify a level?'),('不算。现在先谈群聊安排，不把次数写成认证。','No. Discuss the group plan now instead of recording counts as certification.'),('店明天开业，牌子还是旧时间。谁负责换？','The shop opens tomorrow; the sign still has the old time. Who changes it?'),('还没说。要把旧牌子换成新牌子，不是已经换了。','Unstated. The sign needs replacement; it is not replaced yet.'),('实际上她还没报名；握手也不是所有事项都同意。十个人左右还是大概数。','In fact she has not registered; a handshake is not agreement to everything; about ten is approximate.'),('明白，组合两条信息，照新通知安排，再等本人回答。','Understood; combine the two messages, follow the new notice, and await the person’s answer.')],[('detail','Has the sign been replaced?',['Not yet','Yes','The speaker states it is already new'],0),('inference','Does a handshake approve every item?',['No','Yes','If a game ended'],0)],[],True),
('Keep the facts and the people','Read the final reflection.',[('问题仍然存在，谈过和谈判结束不同；先谈时间，再谈地点。','The problem remains; discussion differs from a finished negotiation; discuss time before location.'),('这个包属于她，具体事务属谁负责要问本人；结实的袋子也不装任意重量。','The bag is hers; ask who is responsible for matters; a sturdy bag does not hold any weight.'),('发动朋友参加自愿活动，不替别人报名；一个意见不左右所有人的决定。','Mobilize friends for voluntary participation without registering for them; one opinion does not control everyone.'),('气候资料是长期范围，不代替今天的天气；联合国名字不是正式声明的证明。','Climate concerns a longer period, not today’s weather; a United Nations name does not prove an official statement.'),('小说里去世和死去是不同语气的人物经历，人类话题也尊重个人，不冒雨替人决定。','去世 and 死去 describe a fictional death with differing registers; discussions of humanity respect individuals and do not make decisions for others while braving rain.'),('祝愿光明的明天，不保证结果。照相先问本人，牌子换没换先看记录，不随意否认。','Wish for a hopeful tomorrow without guarantees; ask before taking photos; check whether the sign changed rather than deny arbitrarily.')],[('mainidea','What should the final chat preserve?',['Actual facts, limits and each person’s decision','Unit counts as level certification','A handshake as universal consent'],0)],[(2,'发动')],False),
('The last message stays open','Read an original verse.',[('旧牌换新，先问谁换。','Old sign to new: first ask who changes it.'),('谈了不等于答应，祝愿不等于保证。','Discussion is not agreement; wishes are not guarantees.'),('群聊留一句，等你自己说。','Leave a line in the group chat, awaiting your own words.')],[('inference','Why leave the last line open?',['To wait for the person’s actual answer','To assume everyone agreed','To certify the level'],0)],[],False),
dict(tf=[('开业','店明天开业，今天没开。','The shop opens tomorrow, not today.','It is open today.',False,'Today’s opening is denied.'),('属于','包属于她，别人还没得到拿的许可。','The bag is hers; others lack permission to take it.','Ownership and permission differ.',True,'The owner does not automatically authorize others.')],reply=[('谈判','谈过就算同意吗？','Does discussing count as agreement?',['不算，要等真实回答。','握手就是所有同意。','游戏结束就自动同意。'],0,'Wait for an actual agreement.'),('左右','十个人左右是精确数吗？','Is about ten people exact?',['不是，还要实际统计。','正好十人已确定。','联合国名字就代表精确。'],0,'Approximation is not precision.')],fill=[('实际上','实际上她还没报名。','In fact she has not registered.'),('组合','把两条信息组合起来看。','Consider the two messages together.')],match=[('牌子',[('要把旧牌子换成新牌子。','The old sign needs replacement.'),('时间被她改了。','She changed the time.'),('谈过不等于同意过。','Discussion is not agreement.')]),('握手',[('握手以后仍要确认。','Confirm even after a handshake.'),('气候不是今天的天气。','Climate is not today’s weather.'),('单元完成不是等级认证。','Unit completion is not level certification.')])]),
[('Wait for the person','最后那句，等你自己说。','For the last line, I will wait for your own words.','Keep agency.'),('End honestly','学过了，继续练；不假装全会。','It has been studied; keep practising without pretending mastery.','Introduction is not mastery.')],
